local ResidentPrivilegeDialog = Class('ResidentPrivilegeDialog')
---@type SDKService
local SDKService = import('Game.Entry.SDKService')
local KTool = CS.Engine.Lib.KTool
local playerComponent = GameUtils.GetEntityCompByType(ECSComponentType.Constants.PlayerComponent)
local NodePath = "Game.UI.ResidentEvent.ResidentPrivilegeCell"
local MaxCount = 8
function ResidentPrivilegeDialog:__init()
    self.node = nil
    self.nodeEnv = nil
    self.isPlayAni = false
end

function ResidentPrivilegeDialog:__delete()
    self.node = nil
    self.nodeEnv = nil
    self.content = nil
    self.isPlayAni = false
end

function ResidentPrivilegeDialog:Awake()
    self.__EventSdkEvent = Events.AddListener(Constants.EventNames.EVENT_SDK, Bind(self, self.OnEventSdkEvent))
    CfUtils.FillText(self.Price, '')
    self:AddUIClick()
    self:InitContent()
    self:InitUIShow()
end

function ResidentPrivilegeDialog:InitUIShow()
    self.node = {}
    self.nodeEnv = {}
    table.insert(self.node,self.EquityItem1.gameObject)
    local allPrivilege = CfUtils.GetCf(AutoIds.IdSetting6263, "PrivilegeCardSortVo", true)
    self.showData = {}
    for i, v in pairs(allPrivilege) do
        local num = GameUtils.GetPrivilegeCardAddNumByRefId(1,v.id,true)
        if num > 0 then
           table.insert(self.showData,v)
        end
    end

    table.sort(self.showData,function(a,b) return a.sort < b.sort  end)

    for i = 1, MaxCount do
        local node = self.node[i]
        if isNull(node) then
            node = CS.UnityEngine.GameObject.Instantiate(self.EquityItem1.gameObject)
            if not isNull(node) then
                KTool.SetParent(node,self.EquityGroup.gameObject,false)
                node.name = "EquityItem"..i
                table.insert(self.node,node)
            end
        end

        if node then
            local env = CfUtils.GetLuaScr(node,NodePath)
            if env then
                env:InitUIData(self.showData[i],i)
                env:PlayerHideAni()
                table.insert(self.nodeEnv,env)
            end
        end
    end
end

function ResidentPrivilegeDialog:InitContent()
    local vo = CfUtils.GetCfVo(AutoIds.IdSetting4032, "WelfareSettingVo", 1)
    self.privilegeCardID = tonumber(vo.giftId)
    self.content = ""
    if vo then
        self.content = vo.text
        self.content = string.gsub(self.content, "\\n", "\n")
    end
end

