function ResidentPrivilegeDialog:Refresh(data)
    if not data then return end
    xRecord.record('4-007')
    self.data = data
    GameUtils.Request(Interfaces.PrivilegeCard,{},function(request,response)
        if  checkInt(response.errCode) == 0  then
            local data = response.data
            if playerComponent then
                ---@type PlayerDojo
                local playerDojo = playerComponent.playerDojo
                playerDojo.overseaPrivilegeCard[tostring(self.privilegeCardID)] = self:GetPrivilegeCardInfo(data.privilegeCard)
                playerDojo:RegGlobalTalentPrivilegeCard()
            end
            self:RequestShow(data.privilegeCard)
            self:PlayNodeAni()
        end
    end )
end

function ResidentPrivilegeDialog:PlayNodeAni()
    if self.isPlayAni then
        return
    end
    for i, v in pairs(self.nodeEnv) do
        v:PlayerHideAni()
        v:PlayerDelayAni(i)
    end
    self.isPlayAni = true
end

function ResidentPrivilegeDialog:RequestShow(data)
    self.cardData = self:GetPrivilegeCardInfo(data)
    if self.cardData then
        local isBuy = false
        if isSet(self.cardData,"roundLeftDay") and isSet(self.cardData,"leftSeconds") then
            local leftSeconds = self.cardData.leftSeconds
            local endTimeTick = self.cardData.endTime
            local curTimeTick = os.time()
            if leftSeconds > 0 and endTimeTick > curTimeTick then
                isBuy = true
            end
        end
        self:SetNodeState(isBuy)
        local payInfo = self.cardData
        local windowsPriceId = CfUtils.GetWindowsPriceId(payInfo)
        local str = localize("<size=40>_YUAN_</size>_num_<size=30>/月</size>" , {_YUAN_ = CfUtils.GetCurrerySymbol(), _num_ = CfUtils.GetPrice(windowsPriceId , payInfo.channelProductId) })
        if CfUtils.isTH() and payInfo.localePrice then
            str = localize("<size=40>_YUAN_</size>_num_<size=30>/月</size>" , {_YUAN_ = payInfo.localeCurrencyCode, _num_ = payInfo.localePrice })
        end
        CfUtils.FillText(self.Price,str)
        if isBuy then
            self.AniRoot:Play("ResidentPrivilegeDialog_Active")
            if GameUtils.isZmFunction() then
                KTool.SetActive(self.Android.gameObject, true)
                KTool.SetActive(self.IOS.gameObject, false)
            else
                KTool.SetActive(self.Android.gameObject,not KTool.UNITY_IOS())
                KTool.SetActive(self.IOS.gameObject,KTool.UNITY_IOS())
            end

            local leftTime = checkNumber(self.cardData.roundLeftDay)
            local str = localize("剩余:_num_天",{_num_ = leftTime})
            if leftTime <= 1 then
                str =  localize("剩余:_num_",{_num_ = CfUtils.GetTimeHMS10(self.cardData.leftSeconds)}) 
            end
            CfUtils.FillText(self.TxtTime,str)
        else
            if GameUtils.isZmFunction() then
                KTool.SetActive(self.FirstPayFree,false)
            else
                local isFirstOpen = true
                if isSet(self.cardData,"isFirstOpen") then
                    isFirstOpen = not (self.cardData.isFirstOpen == 0)
                end
                KTool.SetActive(self.FirstPayFree,isFirstOpen)
                if isFirstOpen then
                    local vo = CfUtils.GetCfVo(AutoIds.IdSetting4032, "WelfareSettingVo", 1)
                    local freeDay = GameUtils.GetPrivilegeCardAddNumByName(checkNumber(vo.giftId), "firstReward")
                    local str = localize("首次免费_num_天",{_num_ = freeDay})
                    CfUtils.FillText(self.FirstPayFree,str)
                end
            end

            local isCanBuy = CfUtils.IsCanBuyByFunctionId(267)
            KTool.SetActive(self.Unsubscribed.gameObject,isCanBuy)
        end
    end
end

function ResidentPrivilegeDialog:GetPrivilegeCardInfo(data)
    for i, v in pairs(data) do
        if v.privilegeCardId == self.privilegeCardID then
            return v
        end
    end
    return nil
end

function ResidentPrivilegeDialog:SetNodeState(state)
    KTool.SetActive(self.Unsubscribed.gameObject,not state)
    KTool.SetActive(self.Subscribed.gameObject,  state)
end

function ResidentPrivilegeDialog:OnDestroy()
    self.cardData = nil
    self.data = nil
    self.controller = nil--luabehaviour 中CSharp对象
    if self.__EventSdkEvent then
        Events.RemoveListener(Constants.EventNames.EVENT_SDK, self.__EventSdkEvent)
        self.__EventSdkEvent = nil
    end
    self:Delete()
end

