        CfUtils.ShowModuleToast(nil , [[<size=42><color=#575757>調査支援計画</color></size>
<size=30> <color=#e71f55>購入後、8つの特権が開放されます。</color></size>

<size=42><color=#575757>特権詳細</color></size>
<size=30>1. 店長、店員の気分値消費<color=#e71f55>-20%</color>
2.エモーション上限UP  <color=#e71f55>＋50</color>
3.<color=#e71f55>3倍速</color>作戦開放
4.協同作戦の報酬受取回数<color=#e71f55>＋1</color>
5.毎日無料で投網使用許可を<color=#e71f55>5</color>つ獲得、釣りオードモード開放
6.空便収益 <color=#e71f55>＋20%</color>
7.サイコロのリセット回数＋2回
8.出前気分値消費  <color=#e71f55>-30%</color></size>]])
    else 
        local vo = CfUtils.GetCfVo(AutoIds.IdSetting4032, "WelfareSettingVo", 1)
        local ruleId = GameUtils.GetPrivilegeCardAddNumByName(checkNumber(vo.giftId), "ruleId")
        if not isNull(ruleId) then
            CfUtils.ShowModuleToast(ruleId)
        end
    end 
   
end

function ResidentPrivilegeDialog:OnBtnBuyClick()
    if KTool.UNITY_IOS() and not GameUtils.isZmFunction() then
        CS.Engine.UI.UIModule.OpenDialog({ id = Constants.UITypeIds.ResidentPrivilegeToastPopUp ,parameters = {
            content = self.content,
            confirmCB = function()
                self:OnBuy()
            end
        }})
    else
        if not KTool.IsMobile() then
            --if GameUtils.isZmFunction() then
            self:OnBuy()
            --else
            --    GameUtils.SecondConfirm(localize('当前平台不支持充值，请前往移动平台充值'))
            --end
        else
            self:OnBuy()
        end
    end
end

function ResidentPrivilegeDialog:OnBuy()
    local isCanBuy = CfUtils.IsCanBuyByFunctionId(267)
    if not isCanBuy then
        GameUtils.Toast(localize("敬请期待"))
        return
    end
    xRecord.record('4-008')
    local payInfo = self.cardData
    if payInfo then
        SDKService:GetInstance():PayMoney({
            productId = payInfo.productId,
            channelProductId = payInfo.channelProductId,
            productDesc = localize("订阅特权"),
            payAmount = payInfo.price,
            data = payInfo
        })
    end
end

--支付成功
function ResidentPrivilegeDialog:OnEventSdkEvent(parameters)
    --- sdk pay succeed
    if parameters.event == Constants.EventNames.EVENT_SDK_PAY then
        GameUtils.Request(Interfaces.PrivilegeCard,{},function(request,response)
            if  checkInt(response.errCode) == 0  then
                local data = response.data
                if playerComponent then
                    ---@type PlayerDojo
                    local playerDojo = playerComponent.playerDojo
                    playerDojo.overseaPrivilegeCard[tostring(self.privilegeCardID)] = self:GetPrivilegeCardInfo(data.privilegeCard)
                    playerDojo:RegGlobalTalentPrivilegeCard()
                    ---添加体力上限的逻辑
                    playerDojo.hpLimit = checkNumber(playerDojo.hpLimit) + checkNumber(GameUtils.GetPrivilegeCardAddNumByName(self.privilegeCardID, "ApMax"))
                    AppService:GetInstance():UpdateRecoveryValueMax(playerDojo.hpLimit)
                end
                self:RequestShow(data.privilegeCard)
                xRecord.af_internal('pay_sub_card')
            end
        end )
    end
end

return ResidentPrivilegeDialog